SELECT  FROM cw_knowledge_gap
WHERE scope_id = #{scopeId}
ORDER BY miss_count DESC, last_seen_at_ms DESC
LIMIT #{limit}

SELECT  FROM cw_knowledge_gap WHERE scope_id = #{scopeId}


        AND (category NOT IN ('NON_BUSINESS', 'REALTIME') OR priority = 'HIGH')

    AND category = #{view}

ORDER BY (priority = 'HIGH') DESC, miss_count DESC, last_seen_at_ms DESC
LIMIT #{limit}

SELECT  FROM cw_knowledge_gap
WHERE scope_id = #{scopeId} AND question_hash = #{questionHash}
LIMIT 1

