SET category = #{row.category}, priority = #{row.priority}, classification_origin = 'MANUAL',
    classification_reason = #{row.classificationReason}, review_revision = review_revision + 1,
    reviewed_by = #{row.reviewedBy}, reviewed_at_ms = #{row.reviewedAtMs}
WHERE scope_id = #{row.scopeId} AND question_hash = #{row.questionHash}
  AND review_revision = #{expectedRevision}
